import os
import time
from datetime import datetime
from collections import defaultdict

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation, log_result, log_warning
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import get_bts_name_from_bts_info


@log_input_and_output
def parse_report_content(file_path):
    """
    Parses report content from results file downloaded from 5G Downlink/Uplink/Performance Test Page.

    :param file_path: full path to file which user wants to parse.
    :type file_path: str
    :return: tuple with content of test results, cumulative results and partial results table,
    saved to three separate dictionaries.
    :rtype: tuple(dict, dict, dict)
    """
    tables = {'Test parameters': {},
              'Cumulative results': {},
              'Partial results': {}}
    mode = 'table'
    table_name = None
    column_names = []

    max_retries = 3
    retry_delay = 2
    for attempt in range(1, max_retries + 1):
        try:
            with open(file_path, mode='r') as lines:
                for line in lines:
                    line = line.strip()

                    if mode == 'table' and _get_new_table_name(line):
                        table_name, mode = _start_new_table(line)
                    elif mode == 'headers':
                        column_names, mode = _set_headers(line, tables, table_name)
                    elif mode == 'rows':
                        mode = _set_rows(line, tables, table_name, column_names)
            break

        except FileNotFoundError:
            files = os.listdir(file_path.rsplit('/', 1)[0])
            if attempt <= max_retries - 1:
                log_warning(f"File {file_path} not found. All files in searched directory: {files}. "
                            f"Retrying open the file... attempt {attempt}/{max_retries}.")
                time.sleep(retry_delay)
            else:
                raise FileNotFoundError(f"File {file_path} not found. All files in searched directory: {files}.")

    return tables['Test parameters'], tables['Cumulative results'], tables['Partial results']


@log_input_and_output
def check_content_of_test_results(carrier_freq, file_path, input_text='lorem ipsum', carrier_unit='MHz'):
    """
    Checks if file saved from 'save test results' button from
    Conformance Test Page -> Conformance Test -> Downlink/Uplink -> Conformance Test Status
    contains information given in test results input box and if carrier frequency value that shows up on
    page is equal to carrier frequency value inside the results file.

    :param carrier_freq: Carrier frequency to check, if empty string is provided then validation is being omitted.
    :type: carrier_freq: str/None
    :param file_path: Full path to test results file.
    :type: file_path: str
    :param input_text: Text expected to be in file from input box on Conformance Test Page -> Conformance Test.
    :type: input_text: str
    :param carrier_unit: Unit of carrier frequency, if empty string is provided then validation is being omitted.
                 ('MHz' on default).
    :type: carrier_unit: str
    :return: True if content is in given results file, False otherwise.
    :rtype: Bool
    """

    with open(file_path, 'r') as f:
        content = f.read()

    carrier_freq_in_result = str(carrier_freq) in content if carrier_freq else True
    unit_in_result = carrier_unit in content if carrier_unit else True

    return carrier_freq_in_result and unit_in_result and input_text in content


@log_input_and_output
def setup_test_model_file_name_with_path(test_type, nr_cell, connection, download_dir='/tmp', report_id=1):
    """
    Setups file name with path for test module report from WebUI as it is built in generic way by OAM with
    parameters mentioned below.

    :param test_type: Test type user wants to check, for example "PUSCH" or "downlink". May be provided lowercase.
    :type test_type: str
    :param nr_cell: Cell ID.
    :type nr_cell: str
    :param connection: Connection to use, can be an alias or AdminConnection object, 'admin' at default.
    :type connection: str or AdminConnection object.
    :param download_dir: Download directory of test report, default '/tmp'
    :type download_dir: str
    :param report_id: order number of report file saved in given download_dir;
                      any other ID than 1 will result in adding order number to file name,
                      i.e. report_id=2 will add (1) postfix into file name;
                      defaults to 1 (first report file saved in directory with no postfix in file name).
    :type report_id: int
    :return: Full test module results file path.
    :rtype: str
    """

    date = datetime.date(datetime.now())
    log_result("Read today's date: {0}".format(date))

    tl_number = get_bts_name_from_bts_info(connection=connection)
    log_result("Read testline number: {0}".format(tl_number))

    return _generate_test_model_file_path(download_dir, test_type, tl_number, nr_cell, date, int(report_id))


def parse_admin_test_results(results):
    """
    Group parameters and their values from the admin API test results into a dictionary,
    using parameters as keys and lists of values as values
    Additionally, change the time format from Unix timestamp to datetime object.
    e.g {'timeReceived': ['14:30:17', '14:30:18'], 'rssi': [-113.5907822, -113.6028442], ...}

    :param results: Admin API test results.
    :type results: list of dict
    :return: Grouped parameters and their values.
    :rtype: dict
    """

    grouped_params = defaultdict(list)

    for result in results:
        for key, value in result['requestMessage'].items():
            grouped_params[key].append(str(datetime.fromtimestamp(value).time()) if key == 'timeReceived' else value)

    return grouped_params


def remove_initial_results(results, first_n_to_remove=1):
    """
    Remove initial results from the test results.

    :param results: Parsed test results.
    :type results: dict
    :param first_n_to_remove: Number of first results to remove.
    :type first_n_to_remove: int
    :return: Test results without first n results.
    :rtype: dict
    """
    return {param: values[first_n_to_remove:] for param, values in results.items()}


@log_input_and_output
def _generate_test_model_file_path(download_dir, test_type, tl_number, nr_cell, date, report_id):
    """
    Generates test module file path for provided data in arguments.

    :param download_dir: Download directory of test report.
    :type download_dir: str
    :param test_type: Test type user wants to check, for example "PUSCH" or "downlink". May be provided lowercase.
    :type test_type: str
    :param tl_number: Testline number read via admin cli.
    :type tl_number: str
    :param nr_cell: Cell ID.
    :type nr_cell: str
    :param date: Today's date read via datetime library.
    :type date: datetime.date object
    :param report_id: order number of report file saved in given download_dir;
                      any other ID than 1 will result in adding order number to file name,
                      i.e. report_id=2 will add (1) postfix into file name;
                      defaults to 1 (first report file saved in directory with no postfix in file name).
    :type report_id: int
    :return: Full test module report file path.
    :rtype: str
    """
    file_id = f"({report_id - 1})" if report_id > 1 else ""

    if test_type.lower() == "uplink" or test_type.lower() == "downlink":
        log_operation(f"Creating file path for {test_type} test module.")
        file_name = f"5G_{test_type.lower().capitalize()}Test_{tl_number}_NRCELL-{nr_cell}_{date.strftime('%Y%m%d')}{file_id}"

    else:
        log_operation("Creating file path for performance test module.")
        file_name = f"5G_PerformanceTest_{test_type.upper()}_{tl_number}_NRCELL-{nr_cell}_{date.strftime('%Y%m%d')}{file_id}"

    exact_file_path = _check_if_file_exists_and_return_exact_path(download_dir, file_name)
    log_result(f"Created file path: {exact_file_path}")

    return exact_file_path


def _start_new_table(line):
    return _get_new_table_name(line), 'headers'


def _get_new_table_name(line):
    table_names = {'Test parameters': 'Test parameters',
                   'Cumulative results': 'Cumulative results',
                   'Partial results': 'Partial results'}

    return table_names.get(line, None)


def _set_headers(line, tables, table_name):
    column_names = [column_name.strip() for column_name in line.split('  ') if column_name]
    tables[table_name] = {column_name: [] for column_name in column_names}

    return column_names, 'rows'


def _set_rows(line, tables, table_name, column_names):
    if not line:
        return 'table'

    elif not line.startswith('---'):
        cells = [cell.strip() for cell in line.split('  ') if cell]

        for column_id, column_name in enumerate(column_names):
            cell = cells[column_id]
            tables[table_name][column_name].append(cell)

    return 'rows'


@log_input_and_output
def _check_if_file_exists_and_return_exact_path(file_dir, file_name, attempts=3):
    """
    Check if file exists in the provided directory and return its exact path (including the extension).

    :param file_dir: File directory.
    :type file_dir: str
    :param file_name: File name (without extension) to check.
    :type file_name: str
    :param attempts: Number of attempts to find the file.
    :type attempts: int
    :return: File absolute path (with extension .txt or not) if exists e.g.
            '/home/ute/Desktop/CRT/TEST_2024-11-29/15:02:34_[1][1.0]_General_PRACH/5G_PerformanceTest_PRACH_7_16_UTE5GSISOAUTO1_NRCELL-1_20241129.txt'
    :rtype: str
    """
    all_files_in_dir = None
    retry_delay = 3
    file_path = os.path.join(file_dir, file_name)

    for attempt in range(1, attempts + 1):
        time.sleep(retry_delay)
        all_files_in_dir = os.listdir(file_dir)
        for possible_file_path in [file_path, f"{file_path}.txt"]:
            if os.path.isfile(possible_file_path):
                return possible_file_path

        log_warning(f"File with name: {file_name} was not found. All files in searched directory: {all_files_in_dir}. "
                    f"Retrying find the file... attempt {attempt}/{attempts}.")

    raise FileNotFoundError(f"File with name: {file_name} was not found. All files in searched directory: {all_files_in_dir}.")
